  final ch.ethz.ssh2.Session sess;
  try {
    sess = this.getClient().openSession();
    this.message(command);
    sess.execCommand(command, host.getEncoding());
    BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(new StreamGobbler(sess.getStdout())));
    BufferedReader stderrReader = new BufferedReader(new InputStreamReader(new StreamGobbler(sess.getStderr())));
    while (true) {
      String line = stdoutReader.readLine();
      if (null == line) {
        break;
      }
      this.log(false, line);
    }
    StringBuilder error = new StringBuilder();
    while (true) {
      String line = stderrReader.readLine();
      if (null == line) {
        break;
      }
      this.log(false, line);
      if (StringUtils.isNotBlank(error.toString())) {
        error.append(" ");
      }
      error.append(line).append(".");
    }
    if (StringUtils.isNotBlank(error.toString())) {
      this.error(error.toString(), null);
    }
  } catch (IllegalStateException | UnsupportedEncodingException | NullPointerException | IndexOutOfBoundsException | ConnectionCanceledException | ClassCastException e) {
    this.error("Runtime exception occurred: " + e.getMessage(), e);
  } finally {
    if (sess != null) {
      sess.close();
    }
  }
}
